import random
from typing import List

# Generator for a line-oriented text file suitable for linenoiseHistoryLoad
# The file consists of newline-delimited history entries. Entries can be empty,
# contain spaces, tabs, Unicode, escape sequences, and very long lines. The
# function returns bytes that represent the entire file contents.

ASCII_WORDS = [
    "help", "exit", "quit", "list", "show", "set", "get", "history",
    "save", "load", "print", "echo", "version", "status", "config",
]

SPECIAL_PREFIXES = [
    "#",      # comment-like
    ";",      # ini-like
    ":",      # vim-like
    "/",      # path-like
    "~/",     # home path
    "./",     # relative path
    ".. /",   # odd spacing
]

UNICODE_FRAGMENTS = [
    "π", "λ", "你好", "😀", "ß", "¡Hola!", "русский", "العربية", "日本語",
]

ESC_SEQ_FRAGMENTS = [
    "\t", "\r", "\u001b[31m", "\u001b[0m", "\\n", "\\t", "\u0000",
]

QUOTED_PATTERNS = [
    '"quoted value"',
    "'single quoted'",
    '"with spaces and tabs\tinside"',
]

OPERATORS = ["=", ":", "->", "=>", "::", "+=", "-=", "|", "||", "&&"]

PATHS = [
    "/etc/linenoise.conf", "/var/log/syslog", "/tmp/test.txt",
    "C:/Windows/System32", "../relative/path", "./script.sh",
]

ENV_VARS = ["$HOME", "$PATH", "$SHELL", "${USER}"]


def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return rng.choice(items)


def _make_ascii_cmd(rng: random.Random) -> str:
    cmd = _rand_choice(rng, ASCII_WORDS)
    parts = [cmd]
    # add arguments
    argc = rng.randint(0, 5)
    for _ in range(argc):
        choice = rng.randint(0, 4)
        if choice == 0:
            parts.append(_rand_choice(rng, ASCII_WORDS))
        elif choice == 1:
            parts.append(_rand_choice(rng, PATHS))
        elif choice == 2:
            parts.append(_rand_choice(rng, ENV_VARS))
        elif choice == 3:
            parts.append(str(rng.randint(-100000, 100000)))
        else:
            parts.append(_rand_choice(rng, QUOTED_PATTERNS))
    # maybe connect with operators
    if rng.random() < 0.3 and len(parts) >= 2:
        i = rng.randrange(1, len(parts))
        parts.insert(i, _rand_choice(rng, OPERATORS))
    return " ".join(parts)


def _make_unicode_line(rng: random.Random) -> str:
    base = _make_ascii_cmd(rng)
    inserts = rng.randint(1, 4)
    for _ in range(inserts):
        pos = rng.randrange(0, len(base) + 1)
        frag = _rand_choice(rng, UNICODE_FRAGMENTS)
        base = base[:pos] + frag + base[pos:]
    return base


def _make_escaped_line(rng: random.Random) -> str:
    segs = []
    n = rng.randint(1, 6)
    for _ in range(n):
        t = rng.randint(0, 3)
        if t == 0:
            segs.append(_make_ascii_cmd(rng))
        elif t == 1:
            segs.append(_rand_choice(rng, ESC_SEQ_FRAGMENTS))
        else:
            segs.append(_rand_choice(rng, UNICODE_FRAGMENTS))
    return " ".join(segs)


def _make_long_line(rng: random.Random, target_len: int) -> str:
    # Build a long but valid, printable-ish line
    chunks: List[str] = []
    while sum(len(c) for c in chunks) < target_len:
        choice = rng.randint(0, 4)
        if choice == 0:
            chunks.append(_make_ascii_cmd(rng))
        elif choice == 1:
            chunks.append(_make_unicode_line(rng))
        elif choice == 2:
            chunks.append(_rand_choice(rng, PATHS))
        elif choice == 3:
            chunks.append(str(rng.getrandbits(32)))
        else:
            chunks.append(_rand_choice(rng, QUOTED_PATTERNS))
    s = " ".join(chunks)
    # Trim exactly to target range to avoid exceeding global cap
    return s[:target_len]


def _make_empty_or_whitespace_line(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ""
    # random whitespace mix
    whites = [" ", "\t"]
    return "".join(rng.choice(whites) for _ in range(rng.randint(1, 20)))


def _make_commentish_line(rng: random.Random) -> str:
    prefix = _rand_choice(rng, SPECIAL_PREFIXES)
    if rng.random() < 0.3:
        return prefix
    return prefix + _make_ascii_cmd(rng)


def _make_path_heavy_line(rng: random.Random) -> str:
    parts = []
    n = rng.randint(1, 5)
    for _ in range(n):
        parts.append(_rand_choice(rng, PATHS))
        if rng.random() < 0.5:
            parts.append(_rand_choice(rng, OPERATORS))
    return " ".join(parts)


def _build_lines(rng: random.Random, max_bytes: int) -> List[str]:
    lines: List[str] = []

    # Seed with a variety of canonical cases
    lines.append("help")
    lines.append("exit")
    lines.append(_make_ascii_cmd(rng))
    lines.append(_make_unicode_line(rng))
    lines.append(_make_escaped_line(rng))
    lines.append(_make_empty_or_whitespace_line(rng))
    lines.append(_make_commentish_line(rng))
    lines.append(_make_path_heavy_line(rng))

    # Add several more random lines
    extra = rng.randint(5, 25)
    for _ in range(extra):
        t = rng.randint(0, 6)
        if t == 0:
            lines.append(_make_ascii_cmd(rng))
        elif t == 1:
            lines.append(_make_unicode_line(rng))
        elif t == 2:
            lines.append(_make_escaped_line(rng))
        elif t == 3:
            # long lines of varying sizes but keep within cap
            target = rng.randint(64, 512)
            lines.append(_make_long_line(rng, target))
        elif t == 4:
            lines.append(_make_empty_or_whitespace_line(rng))
        elif t == 5:
            lines.append(_make_commentish_line(rng))
        else:
            lines.append(_make_path_heavy_line(rng))

    # Occasionally ensure a very long final line to exercise buffers
    if rng.random() < 0.5:
        lines.append(_make_long_line(rng, rng.randint(1024, 2048)))

    # Ensure we don't exceed max_bytes when joined with newlines
    b = []
    total = 0
    for i, line in enumerate(lines):
        # Each line will get a newline except possibly the last; we allow both
        # with and without trailing newline randomly.
        sep = "\n" if (i < len(lines) - 1 or rng.random() < 0.7) else ""
        encoded = (line + sep).encode("utf-8", errors="strict")
        if total + len(encoded) > max_bytes:
            # try to truncate the line to fit
            remaining = max_bytes - total
            if remaining <= 0:
                break
            # Reserve space for potential newline at end only if any remaining
            trunc = (line).encode("utf-8", errors="strict")
            if len(trunc) > remaining:
                trunc = trunc[:remaining]
            b.append(trunc)
            total += len(trunc)
            break
        b.append(encoded)
        total += len(encoded)

    return [chunk.decode('utf-8', errors='ignore') for chunk in b]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    max_size = 4096

    # Build the lines and concatenate. We already ensured size cap while building.
    # Join the decoded chunks safely as they were encoded earlier.
    chunks = _build_lines(rng, max_size)
    data = "".join(chunks)

    # Ensure final encoding and hard cap
    out = data.encode("utf-8", errors="strict")
    if len(out) > max_size:
        out = out[:max_size]
    return out
